// Générateurs du compagnon du MJ (PNJ, taverne, butin, rumeur, météo, rencontres)
/* ---------- Outils du MJ : générateurs en un clic et rencontres aléatoires ---------- */
const pkr=a=>a[rnd(a.length)-1];
const dsum=(n,s)=>{let t=0;for(let i=0;i<n;i++)t+=rnd(s);return t;};
const ucf=s=>s?s.charAt(0).toUpperCase()+s.slice(1):s;
const GEN=()=>{const g=S.gen||(S.gen={});if(!g.k)g.k='pnj';g.o=g.o||{};g.hist=g.hist||[];g.env=g.env||'foret';if(g.dif==null)g.dif=1;return g;};
const genMon=ids=>{for(const id of [].concat(ids)){const m=getMon(id);if(m)return m;}return null;};

