const gdr=(s,g)=>String(s).replace(/\{([^|{}]*)\|([^|{}]*)\}/g,(x,a,b)=>g?b:a);
const NPC_HOOK=['propose 50 po pour escorter une charrette jusqu’au prochain village','cherche quelqu’un pour récupérer un objet volé par des gobelins','a besoin qu’on enquête sur la disparition d’un proche','veut faire porter un message discret à un rival','offre une information précieuse contre un service','demande une protection pour la nuit : on le suit','paie bien pour qu’on retrouve un chien de chasse égaré dans les bois','veut qu’on récupère une dette auprès d’un client de mauvaise foi'];
function genName(a,g){const f=pkr(g?a.f:a.m);if(a.v)return rnd(3)===1?pkr(a.v):f;if(a.k==='drakéide')return pkr(a.s)+' '+f;if(a.k==='demi-orc')return rnd(2)===1?f+' '+pkr(a.s):f;return f+' '+pkr(a.s);}
function pickAnc(k){if(k){const a=NPC_ANC.find(x=>x.k===k);if(a)return a;}const t=NPC_ANC.reduce((s,a)=>s+a.w,0);let r=rnd(t);for(const a of NPC_ANC){r-=a.w;if(r<=0)return a;}return NPC_ANC[0];}
function npcCore(o){o=o||{};const a=pickAnc(o.anc);const g=o.g==='f'?1:o.g==='m'?0:rnd(2)-1;const job=o.job||pkr(NPC_JOB);
  const p1=pkr(NPC_PERS);let p2=pkr(NPC_PERS);while(p2===p1)p2=pkr(NPC_PERS);
  const f1=pkr(NPC_FEAT);let f2=pkr(NPC_FEAT);while(f2===f1)f2=pkr(NPC_FEAT);
  return {a,g,name:genName(a,g),job,jobN:job[g],anc:a.n[g],build:pkr(NPC_BUILD)[g],age:a.k==='elfe'?'à l’âge difficile à deviner':pkr(NPC_AGE),f1,f2,p1:p1[g],p2:p2[g],tic:gdr(pkr(NPC_TIC),g)};}
function genPnj(o){const c=npcCore({anc:o.anc,g:o.g});const il=c.g?'elle':'il';const un=c.g?'une':'un';
  const st=genMon(c.job[2]);const att=pkr(NPC_ATT);
  return {k:'pnj',t:c.name,s:`${ucf(c.anc)} · ${c.jobN}`,
   p:[`${c.name} est ${un} ${c.anc} ${c.build} ${c.age}, avec ${c.f1} et ${c.f2}. ${ucf(c.jobN)} de son état, ${il} est ${c.p1} et ${c.p2} ; ${il} ${c.tic}.`],
   d:[['Voix',ucf(pkr(NPC_VOICE))],['Idéal',ucf(pkr(NPC_IDEAL))],['Ce qu’'+il+' veut',ucf(pkr(NPC_WANT))],['Secret (MJ)',ucf(pkr(NPC_SECRET))],['Attitude',`${att[0]} : ${att[1]}`],['Accroche',ucf(pkr(NPC_HOOK))]].map(([a,b])=>[a,gdr(b,c.g)]),
   mons:st?[{id:st.id,q:1,lab:'Profil de jeu'}]:[]};}

