function genTaverne(o){const tier=TAV_TIER.find(t=>t.k===o.tier)||pkr(TAV_TIER);const ty=pkr(TAV_TYPE.filter(x=>x[2].split(' ').includes(tier.k)));const tg=ty[1]==='f'?1:0;
  const n1=pkr(TAV_N);const adj=pkr(TAV_A);const art=(n,cap)=>n[2]?(cap?'L’':'l’'):n[1]==='f'?(cap?'La ':'la '):(cap?'Le ':'le ');
  let name;const r=rnd(10);
  if(r<=6)name=art(n1,1)+n1[0]+' '+adj[n1[1]==='f'?1:0];
  else if(r<=9){let n2=pkr(TAV_N);while(n2===n1)n2=pkr(TAV_N);name=art(n1,1)+n1[0]+' et '+art(n2,0)+n2[0];}
  else{const c=npcCore({});name='Chez '+c.name.split(' ')[0];}
  const host=npcCore({job:['tenancier','tenancière',['commoner']]});const hil=host.g?'elle':'il';
  const ru=genRumeur({}).p[0];
  const typeN=ty[0];const un=tg?'une':'un';
  return {k:'taverne',t:name,s:`${ucf(typeN)} ${tier.n}`,
   p:[`${name} est ${un} ${typeN} ${tier.n} ${pkr(TAV_LOC)[tg]}. ${pkr(tier.amb)} Ce soir, on y croise ${pkr(TAV_CROWD)}.`,
      `Derrière le comptoir : ${host.name}, ${host.g?'une':'un'} ${host.anc} ${host.p1} avec ${host.f1} ; ${hil} ${host.tic}.`],
   d:[['Particularité',pkr(TAV_FEAT)],['En ce moment',pkr(TAV_EVENT)],['Plat du jour',pkr(TAV_FOOD)+' · '+tier.meal],['À boire',pkr(TAV_DRINK)+' · chope '+tier.ale],['Chambre',tier.room],['On y entend',ru]],
   mons:[]};}

/* --- Rumeur --- */
const RU_LIEU=['le vieux moulin','les ruines du monastère','la tour du marais','la mine abandonnée de Roc-Gris','le cimetière de la colline','les égouts sous le marché','la forêt de Brumesombre','le gué des Pendus','le phare éteint','le manoir des Valcourt','la carrière inondée','le pont du Diable','la chapelle sans toit','l’île aux Corbeaux','le puits asséché du village'];
const RU_SRC=['un marchand ivre','la fille du meunier','un vieux soldat manchot','une lavandière au lavoir','un enfant des rues contre une pièce','un prêtre qui baisse la voix','un colporteur halfelin','une servante de l’auberge','un chasseur revenu bredouille','un garde qui s’ennuie','un barde en mal d’inspiration','une herboriste un peu sorcière'];
const RU_CREA=[['un ours-hibou',['owlbear']],['une harpie',['harpy']],['un troll',['troll']],['une guenaude verte',['green-hag']],['un basilic',['basilisk']],['des goules',['ghoul']],['un feu follet',['will-o-wisp']],['un loup-garou',['werewolf-human','werewolf-hybrid']],['un jeune dragon vert',['young-green-dragon']],['une manticore',['manticore']],['un ettercap et ses araignées',['ettercap']],['un fantôme',['ghost']],['un mimique',['mimic']],['une bande de gobelins',['goblin-warrior','goblin']],['un ogre',['ogre']],['une vouivre',['wyvern']],['un nécrophage',['wight']],['un rat-garou',['wererat-human','wererat-hybrid']],['une gargouille',['gargoyle']],['un doppelganger',['doppelganger']]];
const RU_T=[
 ['On aurait vu {crea} rôder près de {lieu} à la nuit tombée.','Vrai : la créature y a établi son repaire et chasse le bétail.','En partie : il y a bien une menace, mais ce n’est pas la créature décrite.','Faux : un berger a inventé l’histoire pour éloigner les curieux de son alambic clandestin.'],
 ['Le seigneur local serait ruiné et vendrait en secret les bijoux de famille.','Vrai : un receleur de la ville basse en a plusieurs.','En partie : il est endetté, mais c’est son intendant qui vole les bijoux.','Faux : la rumeur est lancée par un rival qui veut faire baisser son crédit.'],
 ['Un trésor serait enterré sous {lieu} : une carte circulerait dans les bas-fonds.','Vrai : la carte existe, et plusieurs bandes la cherchent déjà.','En partie : le « trésor » est un coffre d’archives compromettantes.','Faux : les cartes sont des faux vendus 5 po pièce par un escroc.'],
 ['Les puits du quartier est seraient empoisonnés.','Vrai : une secte prépare une épidémie.','En partie : l’eau est polluée par une tannerie en amont.','Faux : un marchand d’eau a payé pour qu’on le dise.'],
 ['Trois enfants auraient disparu près de {lieu} en une semaine.','Vrai : {crea} les retient prisonniers.','En partie : ils ont fugué et se cachent là-bas pour échapper à un patron brutal.','Faux : ils sont partis avec une troupe de saltimbanques, avec l’accord de leurs parents.'],
 ['Le grand prêtre ne vieillirait plus depuis vingt ans.','Vrai : il boit une potion tirée d’un rituel interdit.','En partie : il utilise un déguisement magique pour masquer ses rides.','Faux : c’est son fils, qui lui ressemble trait pour trait, qui a pris sa place.'],
 ['Une caravane de soie arrivera la semaine prochaine, presque sans escorte.','Vrai : c’est une occasion en or pour des bandits… ou un contrat d’escorte pour les PJ.','En partie : elle est escortée par des mercenaires déguisés en marchands.','Faux : c’est un piège tendu par la garde pour attraper des brigands.'],
 ['On entendrait des cloches sonner la nuit à {lieu}, alors qu’il n’y a plus de cloche.','Vrai : un esprit y attend qu’on lui rende justice.','En partie : des contrebandiers utilisent ce signal pour leurs livraisons.','Faux : c’est le vent dans les ruines, rien de plus.'],
 ['Le forgeron aurait forgé une lame qui chante quand on la tire.','Vrai : il a utilisé un minerai venu d’une météorite.','En partie : la lame siffle, à cause d’un défaut de trempe, mais elle est très bonne.','Faux : c’est un coup publicitaire pour vendre plus cher.'],
 ['Les morts du cimetière ne resteraient plus dans leurs tombes.','Vrai : un nécromancien recrute des serviteurs.','En partie : des pilleurs de tombes déterrent les corps la nuit.','Faux : des chiens errants ont retourné la terre.'],
 ['Une sorcière offrirait de réaliser un vœu à qui lui apporte un cœur de cerf blanc.','Vrai : c’est une guenaude, et le prix réel sera bien plus élevé.','En partie : c’est une druide qui protège le cerf et teste les chasseurs.','Faux : c’est une conteuse qui récolte des pièces avec de belles histoires.'],
 ['Le bourgmestre aurait été remplacé par un imposteur.','Vrai : c’est un doppelganger au service d’une guilde.','En partie : il est sous l’emprise d’un sort de charme.','Faux : il a juste arrêté de boire, et ça change un homme.'],
 ['On paierait 100 po pour la tête de {crea} qui terrorise la route du nord.','Vrai : l’avis est affiché à la caserne.','En partie : la prime existe, mais la créature n’est qu’un pion de quelqu’un d’autre.','Faux : la prime a déjà été réclamée le mois dernier.'],
 ['Les mines de Roc-Gris auraient percé une galerie vers un monde sous la terre.','Vrai : des créatures de l’Outreterre remontent.','En partie : on a découvert un ancien temple nain scellé.','Faux : c’est une poche de gaz qui provoque des hallucinations.'],
 ['Une épidémie de cauchemars frappe le village : tous rêvent de la même porte rouge.','Vrai : une guenaude nocturne hante les dormeurs.','En partie : un artefact enfoui émet un appel psychique.','Faux : c’est l’effet d’un pain fait avec du seigle ergoté.'],
 ['Le capitaine de la garde fermerait les yeux sur la contrebande contre un pourcentage.','Vrai : et il a des preuves contre ses supérieurs.','En partie : c’est son second qui touche l’argent en son nom.','Faux : il prépare au contraire une grande rafle.'],
 ['Un dragon aurait été vu au-dessus des montagnes, à l’aube.','Vrai : un jeune dragon cherche un nouveau territoire.','En partie : c’est une vouivre, bien assez dangereuse.','Faux : un mage a lancé une illusion pour faire fuir les bûcherons.'],
 ['Il y aurait un passage secret entre la cave de l’auberge et {lieu}.','Vrai : il sert encore, la nuit.','En partie : le passage existe mais s’est effondré à mi-chemin.','Faux : la cave est seulement très profonde.'],
 ['L’héritier du comte serait un bâtard, et le vrai héritier vivrait parmi les pauvres.','Vrai : et quelqu’un veut le faire disparaître.','En partie : il y a bien un enfant illégitime, mais il ne veut rien réclamer.','Faux : c’est une calomnie d’une famille rivale.'],
 ['Les loups sont trop nombreux cette année : ils suivraient un chef aux yeux rouges.','Vrai : un loup-garou dirige la meute.','En partie : un loup sanguinaire a pris la tête de la meute.','Faux : la disette pousse simplement les loups vers les fermes.'],
 ['Un navire fantôme serait apparu dans la baie, toutes voiles déchirées.','Vrai : son équipage maudit cherche quelque chose à terre.','En partie : c’est un navire pirate qui se fait passer pour un vaisseau fantôme.','Faux : le brouillard et le rhum font le reste.'],
 ['La guilde des marchands chercherait discrètement des aventuriers pour une affaire délicate.','Vrai : un de leurs entrepôts est hanté et ils veulent éviter le scandale.','En partie : c’est une seule marchande, aux abois, qui agit sans la guilde.','Faux : c’est un recruteur pour une expédition suicide.'],
 ['On aurait vu {crea} dans {lieu}, gardant quelque chose de brillant.','Vrai : la créature garde un trésor ancien.','En partie : la créature est là, le trésor est un tas de tessons de verre.','Faux : un reflet de lune sur une armure abandonnée.'],
 ['Une fontaine de la ville exaucerait les vœux à la pleine lune.','Vrai : une fée mineure y vit et adore les marchés.','En partie : on y repêche les pièces, qui financent un orphelinat.','Faux : simple superstition, mais les pièces disparaissent bien quelque part.']];
function genRumeur(o){const t=pkr(RU_T);const cr=pkr(RU_CREA);const m=genMon(cr[1]);const lieu=pkr(RU_LIEU);
  const fill=s=>s.replace(/\{lieu\}/g,lieu).replace(/\{crea\}/g,cr[0]+(m&&m.en?' ('+m.en+')':''));
  const v=rnd(6);const tr=v<=3?[1,'Vraie']:v<=5?[2,'En partie vraie']:[3,'Fausse'];
  const uses=/\{crea\}/.test(t[0]+t[tr[0]]);
  return {k:'rumeur',t:'Rumeur',s:'Source : '+pkr(RU_SRC),
   p:['« '+fill(t[0])+' »'],d:[['Vérité (MJ)',tr[1]+' : '+fill(t[tr[0]]).replace(/^(Vrai|En partie|Faux) : /,'')],['Pour vérifier',pkr(['Interroger trois habitants (Investigation DD 12)','Payer à boire au bon informateur (2 pa et Persuasion DD 13)','Se rendre sur place, de jour','Consulter les registres du temple ou de la mairie (Histoire DD 14)','Suivre la personne qui l’a lancée (Discrétion DD 13)'])]],
   mons:uses&&m?[{id:m.id,q:1,lab:'Créature citée'}]:[]};}

