const TRINK=['Une clé en fer qui n’ouvre aucune serrure connue','Un dé à six faces dont toutes les faces portent un 6','Une lettre d’amour jamais envoyée, signée « A. »','Un œil de verre qui semble suivre les mouvements','Une petite boîte à musique qui joue un air triste','Une dent de dragon (ou de très gros lézard)','Une carte à jouer représentant le porteur, en plus âgé','Un médaillon contenant une mèche de cheveux roux','Une plume d’oiseau qui ne se mouille jamais','Une bougie qui ne s’allume pas','Une pierre plate gravée d’un symbole inconnu','Un petit sablier dont le sable coule vers le haut','Une figurine de chevalier en étain, sans tête','Un mouchoir brodé aux armoiries d’une famille éteinte','Une bourse vide qui tinte quand on la secoue','Un flacon contenant une fumée violette tourbillonnante','Une bague en os sculptée en forme de serpent','Une liste de noms, dont trois sont barrés','Une boussole qui indique toujours la même auberge','Un crâne de rat poli, percé pour servir de pendentif'];
const LOOT_WHERE=[['Dans une bourse en cuir graisseuse','Cousu dans la doublure d’un manteau','Dans une petite boîte en fer-blanc','Noué dans un mouchoir crasseux','Dans une botte, sous la semelle intérieure'],['Dans un coffre bardé de fer au cadenas rouillé (Crochetage DD 15)','Éparpillé parmi les ossements d’anciens aventuriers','Sous une dalle descellée (Investigation DD 14)','Dans des sacs de jute moisis, au fond du repaire','Sur un autel profané, couvert de cire noire','Dans un tonneau à double fond (Perception DD 13)']];
const LOOT_TIERS=[['t1','FP 0 à 4'],['t2','FP 5 à 10'],['t3','FP 11 à 16'],['t4','FP 17+']];
const fmtPo=n=>n.toLocaleString('fr-FR');
function rollCoins(list){const out={};list.forEach(([n,s,m,u])=>{out[u]=(out[u]||0)+dsum(n,s)*m;});return ['pp','po','pe','pa','pc'].filter(u=>out[u]).map(u=>fmtPo(out[u])+' '+u);}
function pickW(rows){const t=rows.reduce((a,r)=>a+r[0],0);let r=rnd(t);for(const x of rows){r-=x[0];if(r<=0)return x[1];}return rows[0][1];}
function lootMagic(rar,n){const L=(typeof MLIST!=='undefined'?MLIST:[]).filter(m=>rar.includes(m.rk));const out=[];for(let i=0;i<n&&L.length;i++){const m=pkr(L);if(!out.includes(m.id))out.push(m.id);}return out;}
function genButin(o){const ti=Math.max(0,LOOT_TIERS.findIndex(t=>t[0]===o.tier));const hoard=o.type==='tresor';const d=[];const p=[];let mi=[];
  const total=coins=>coins.join(', ');
  if(!hoard){const c=rollCoins(pickW(LOOT_IND[ti]));d.push(['Pièces',total(c)]);if(rnd(10)<=3)d.push(['Babiole',pkr(TRINK)]);if(ti>=1&&rnd(10)<=2){const v=[10,50,100,500][Math.min(3,ti)];const g=pkr(GEMS[v]);d.push(['Gemme',`${g[0]}, ${g[1]} (${fmtPo(v)} po)`]);}
    if(rnd(20)<=ti+1){mi=lootMagic(ti<2?['c','u']:['u','r'],1);}
    p.push(`${pkr(LOOT_WHERE[0])} : de quoi récompenser la fouille d’un adversaire (${LOOT_TIERS[ti][1]}).`);}
  else{const H=LOOT_HOARD[ti];d.push(['Pièces',total(rollCoins(H.c))]);
    const ga=pkr(H.ga.filter(x=>x[0]));if(ga&&rnd(10)<=8){const q=dsum(ga[0],ga[1]);const v=ga[2];
      if(ga[3]==='g'){const by={};for(let i=0;i<q;i++){const g=pkr(GEMS[v]);by[g[0]]=by[g[0]]||[g,0];by[g[0]][1]++;}d.push(['Gemmes',Object.values(by).map(([g,k])=>`${k>1?k+' × ':''}${g[0]} (${g[1]})`).join(' ; ')+` · ${fmtPo(v)} po pièce, soit ${fmtPo(q*v)} po`]);}
      else{const L=[];for(let i=0;i<q;i++)L.push(pkr(ARTS[v]));d.push(['Objets d’art',L.join(' ; ')+` · ${fmtPo(v)} po pièce, soit ${fmtPo(q*v)} po`]);}}
    const [mn,mx]=H.mi[1];const n=mn+rnd(mx-mn+1)-1;mi=lootMagic(H.mi[0],n);
    if(rnd(10)<=4)d.push(['Babiole',pkr(TRINK)]);
    p.push(`${pkr(LOOT_WHERE[1])} : le trésor accumulé d’un repaire (${LOOT_TIERS[ti][1]}).`);}
  return {k:'butin',t:hoard?'Trésor de repaire':'Butin individuel',s:LOOT_TIERS[ti][1],p,d,mi,mons:[]};}

/* --- Météo --- */
const MET_SEASONS=[['printemps','Printemps'],['ete','Été'],['automne','Automne'],['hiver','Hiver']];
const MET_CLIM=[['tempere','Tempéré'],['froid','Nordique'],['aride','Désert'],['tropical','Tropical'],['montagne','Montagne']];
const MET_T={tempere:[[4,18],[16,32],[3,17],[-10,6]],froid:[[-8,8],[5,20],[-10,6],[-35,-5]],aride:[[12,34],[28,48],[12,32],[0,22]],tropical:[[22,32],[24,36],[22,33],[20,30]],montagne:[[-5,10],[5,22],[-6,10],[-28,-2]]};
const MET_P={tempere:[[45,30,18,7],[60,20,8,12],[40,32,20,8],[45,30,20,5]],froid:[[50,30,15,5],[55,30,10,5],[40,30,25,5],[40,25,30,5]],aride:[[80,10,4,6],[88,4,2,6],[82,10,3,5],[75,15,6,4]],tropical:[[40,25,20,15],[25,20,25,30],[35,25,20,20],[60,20,12,8]],montagne:[[40,30,20,10],[50,25,10,15],[40,30,22,8],[35,25,35,5]]};
const MET_FLAV={printemps:['Les haies bourgeonnent et les oiseaux s’égosillent dès l’aube.','La terre dégèle et les chemins sentent l’humus.','Les ruisseaux gonflés par la fonte des neiges débordent par endroits.'],ete:['Les cigales crissent sans relâche dans les herbes hautes.','Une odeur de foin coupé flotte sur la campagne.','Les mouches et les taons harcèlent bêtes et voyageurs.'],automne:['Les feuilles mortes crissent sous les pas et cachent les ornières.','L’air sent la fumée de bois et les champignons.','Les vols d’oies sauvages filent vers le sud en criant.'],hiver:['La lumière est basse, et la nuit tombe tôt.','Les arbres nus craquent sous le gel.','Le moindre bruit porte loin dans le silence glacé.']};
function genMeteo(o){const si=Math.max(0,MET_SEASONS.findIndex(x=>x[0]===o.sea));const sea=MET_SEASONS[si][0];const cl=MET_CLIM.find(x=>x[0]===o.cli)?o.cli:'tempere';
  const [lo,hi]=MET_T[cl][si];const t=lo+rnd(hi-lo+1)-1;const tn=t-(cl==='aride'?10+rnd(10):3+rnd(6));
  const w=MET_P[cl][si];const pr=pickW([[w[0],0],[w[1],1],[w[2],2],[w[3],3]]);
  let windR=pickW([[30,0],[40,1],[20,2],[10,3]]);if(cl==='montagne'||cl==='froid')windR=Math.min(3,windR+(rnd(3)===1?1:0));if(pr===3&&windR<2)windR=2;
  const snow=t<=0,sleet=t>0&&t<=2;const sand=cl==='aride'&&pr>=2;
  let sky,ptxt='',ptitle='Aucune';const fx=[];
  if(pr===0){sky=pkr(sea==='automne'||sea==='hiver'?['dg','vo','nu','br','br']:['dg','dg','vo','nu']);}
  else sky='cv';
  const SKY={dg:['Dégagé','Le ciel est d’un bleu limpide, sans le moindre nuage.'],vo:['Voilé','Un voile laiteux adoucit la lumière du soleil.'],nu:['Nuageux','De gros nuages passent et jettent des ombres mouvantes sur le paysage.'],br:['Brouillard','Un brouillard épais colle au sol jusqu’en milieu de matinée.'],cv:['Couvert','Le ciel est bas, uniformément gris.']};
  if(sky==='br')fx.push('Brouillard : zone légèrement obscurcie, et fortement obscurcie au-delà d’une vingtaine de mètres. Désavantage aux tests de Sagesse (Perception) basés sur la vue.');
  if(pr>0){if(sand){ptitle='Tempête de sable';ptxt='Le vent soulève un mur de sable ocre qui avale l’horizon et s’infiltre partout.';fx.push('Tempête de sable : fortement obscurci au-delà de quelques mètres ; sans protection du visage, test de Constitution DD 10 par heure ou un niveau d’épuisement (suggestion).');}
    else if(snow){ptitle=['','Neige légère','Fortes chutes de neige','Blizzard'][pr];ptxt=['','Quelques flocons tombent paresseusement et fondent sur les manteaux.','La neige tombe dru et recouvre les traces en moins d’une heure.','Un blizzard hurlant : on ne distingue plus ses propres mains.'][pr];
      if(pr>=2)fx.push('Neige épaisse : terrain difficile ; zone légèrement obscurcie, désavantage aux tests de Sagesse (Perception) basés sur la vue.');}
    else if(sleet){ptitle='Neige fondue';ptxt='Une neige mouillée tombe et se change en boue glacée sous les pas.';fx.push('Sol glissant : les routes non pavées comptent comme terrain difficile (suggestion).');}
    else{ptitle=['','Bruine','Pluie battante','Orage'][pr];ptxt=['','Une bruine fine et persistante mouille tout sans qu’on s’en rende compte.','Une pluie drue tambourine sans relâche ; les chemins se changent en ruisseaux.','Un orage éclate : éclairs, tonnerre assourdissant et trombes d’eau.'][pr];}
    if(pr>=2&&!sand)fx.push('Précipitations fortes : zone légèrement obscurcie, désavantage aux tests de Sagesse (Perception) basés sur la vue. Les flammes nues s’éteignent.');
    if(pr===3&&!snow&&!sand)fx.push('Foudre (au choix du MJ) : une créature en armure métallique sur un point élevé peut être frappée, 4d10 dégâts de foudre, sauvegarde de Dextérité DD 15 pour moitié.');}
  const WIND=[['Calme','Pas un souffle d’air ; la fumée monte droit.'],['Brise','Une brise légère agite les feuilles et rafraîchit l’air.'],['Vent fort','Le vent souffle par rafales et plaque les capes contre les corps.'],['Tempête','Des bourrasques violentes arrachent les tuiles et couchent les arbres.']];
  if(windR>=2)fx.push('Vent fort : désavantage aux jets d’attaque à distance avec une arme et aux tests de Sagesse (Perception) basés sur l’ouïe. Les flammes nues s’éteignent, le brouillard se disperse, et le vol non magique est presque impossible.');
  let tt;if(t<=-18)tt='Un froid mordant, capable de tuer : l’haleine gèle dans les barbes.';else if(t<=0)tt='Il gèle : le sol craque sous les bottes et les flaques sont prises par la glace.';else if(t<=10)tt='L’air est frais, presque piquant.';else if(t<=20)tt='Une température douce, idéale pour la marche.';else if(t<=30)tt='Il fait chaud ; les montures boivent plus que d’habitude.';else if(t<38)tt='Une chaleur écrasante : l’air tremble au-dessus du sol.';else tt='Une fournaise : le métal des armures devient brûlant au toucher.';
  if(t<=-18)fx.push('Froid extrême : une créature exposée sans vêtements chauds fait un jet de sauvegarde de Constitution DD 10 à la fin de chaque heure, ou subit un niveau d’épuisement. Résistance ou immunité au froid : réussite automatique.');
  if(t>=38)fx.push('Chaleur extrême : sans eau potable, jet de sauvegarde de Constitution à la fin de chaque heure (DD 5, +1 par heure supplémentaire), ou un niveau d’épuisement. Désavantage avec une armure intermédiaire ou lourde, ou des vêtements épais.');
  if(cl==='aride'&&tn<=5)fx.push('Nuit glaciale dans le désert : prévoir couvertures et feu de camp.');
  const evo=pkr(['Le temps devrait se maintenir jusqu’au soir.','Le temps se dégrade en fin de journée : prévoir un abri.','Une éclaircie est attendue dans l’après-midi.','Le vent tourne au crépuscule et apporte une odeur de pluie.','La nuit sera nettement plus froide que la journée.']);
  const p=[[SKY[sky][1],ptxt,tt,WIND[windR][1],pkr(MET_FLAV[sea])].filter(Boolean).join(' ')];
  return {k:'meteo',t:`${SKY[sky][0]}${pr?' · '+ptitle:''}`,s:`${MET_SEASONS[si][1]} · climat ${MET_CLIM.find(x=>x[0]===cl)[1].toLowerCase()}`,p,
   d:[['Température',`${t} °C en journée, ${tn} °C la nuit`],['Ciel',SKY[sky][0]],['Précipitations',ptitle],['Vent',WIND[windR][0]],['Évolution',evo],...(fx.length?[['Effets en jeu',fx.join('\n')]]:[['Effets en jeu','Aucun effet de règle particulier.']])],mons:[]};}

const GEN_KINDS=[['pnj','PNJ','Nom, allure, secret'],['taverne','Taverne','Nom, ambiance, menu'],['butin','Butin','Pièces, gemmes, objets'],['rumeur','Rumeur','Et ce qui est vrai'],['meteo','Météo','Ciel et effets en jeu']];
const GEN_FN={pnj:genPnj,taverne:genTaverne,butin:genButin,rumeur:genRumeur,meteo:genMeteo};
function genRun(k){const g=GEN();g.k=k||g.k;const o=g.o[g.k]||(g.o[g.k]={});const r=GEN_FN[g.k](o);r.id=uid();r.at=Date.now();g.cur=r;g.hist=[r].concat(g.hist.filter(x=>x.id!==r.id)).slice(0,12);return r;}
function genText(r){return [r.t+(r.s?' — '+r.s:''),...(r.p||[]),...(r.d||[]).map(([a,b])=>a+' : '+b),...(r.mi||[]).map(id=>{const m=MI[id];return m?'Objet magique : '+m.n+(m.en?' ('+m.en+')':'')+' · '+(m.r||''):'';}).filter(Boolean),...(r.mons||[]).map(x=>{const m=getMon(x.id);return m?(x.lab||'Créature')+' : '+m.n+(m.en?' — VO : '+m.en:''):'';}).filter(Boolean)].join('\n');}

